// Las ocho clases y sus árboles de habilidades (3 ramas por clase). Cada habilidad es un arquetipo con números.
import type { Clase, Elemento } from '../juego/tipos_objetos';

export type Arquetipo = 'golpe' | 'proyectil' | 'nova' | 'area' | 'invocar' | 'aura' | 'buff' | 'grito' | 'pasiva' | 'teleporte' | 'carga' | 'trampa' | 'maldicion' | 'cadena' | 'salto' | 'torbellino' | 'bomba' | 'cuervos';
export interface Habilidad {
  id: string; nombre: [string, string]; desc: [string, string];
  clase: Clase; rama: 0 | 1 | 2; nivelReq: number; req?: string[];
  tipo: Arquetipo; elem: Elemento; anim: 'atacar' | 'lanzar';
  mana: [number, number];
  /** Daño propio (hechizos): mínimo y máximo a nivel 1, y cuánto sube por nivel (0.15 = 15%). */
  dano?: [number, number, number];
  /** Multiplicador del daño del arma (golpes): % a nivel 1 y % por nivel. */
  mult?: [number, number];
  n?: [number, number];
  radio?: number; vel?: number; perfora?: boolean; explota?: number; duracion?: [number, number];
  buscador?: boolean; rebota?: number;
  efecto: string; sonido: string;
  sinergias?: [string, number][];
  /** Bonos que da (pasivas, auras, buffs, gritos, maldiciones): stat -> [base, por nivel]. */
  bonos?: Record<string, [number, number]>;
  invoca?: string; max?: [number, number];
  /** Recarga en segundos (habilidades grandes). */
  recarga?: number;
  color: string; glifo: string;
  /** Definitiva de la rama (nivel 30): una sola por rama, con recarga. */
  definitiva?: true;
  /** Solo se usa transformado (druida). */
  forma?: 'lobo' | 'oso' | 'cualquiera';
  /** Furia mínima que pide (berserker): la gasta al usarse. */
  furia?: number;
  /** Área o maldición centrada en el héroe en vez del cursor. */
  enHeroe?: true;
  /** Proyectiles en anillo alrededor del héroe. */
  circulo?: true;
}
/** Niveles de las filas del árbol. */
export const TIERS = [1, 6, 12, 18, 24, 30];

const H = (h: Habilidad) => h;
